def searchMountain(nums, target):
    n = len(nums)
    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < nums[mid + 1]:
            lo = mid + 1
        else:
            hi = mid
    peak = lo
    a, b = 0, peak + 1
    while a < b:
        m = (a + b) // 2
        if nums[m] < target:
            a = m + 1
        else:
            b = m
    if a <= peak and nums[a] == target:
        return a
    a, b = peak + 1, n
    while a < b:
        m = (a + b) // 2
        if nums[m] > target:
            a = m + 1
        else:
            b = m
    if a < n and nums[a] == target:
        return a
    return -1
